"""Whether a settled claim's receipt is in the ledger, read from the month listing.

Single-entry `show` is billed per call (docs/ops/ledger-vendor.md), so it is not
used here: one period `list` per month answers for every claim in that month.
Results are not cached, so each screen load reflects the ledger as it is now.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of

BOOKED = "booked"
NOT_BOOKED = "not_booked"


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def for_claims(self, claims):
        """Map claim id -> BOOKED / NOT_BOOKED, or None if the claim is not settled."""
        receipts_by_month = {}
        status = {}
        for claim in claims:
            if claim.status != POSTED or not claim.receipt:
                status[claim.claim_id] = None
                continue
            month = month_of(claim.spent_on)
            if month not in receipts_by_month:
                date_from, date_to = month_bounds(month)
                rows = self.ledger.list_rows(date_from, date_to)
                receipts_by_month[month] = {row.receipt for row in rows}
            found = claim.receipt in receipts_by_month[month]
            status[claim.claim_id] = BOOKED if found else NOT_BOOKED
        return status

